const staticData = $getWorkflowStaticData('global');
const forceRefresh = !!($input.first().json.force_refresh);
const now = Date.now();
const FIVE_MIN = 5 * 60 * 1000;

const cacheValid = !forceRefresh
  && staticData.referenceDataCache
  && (now - staticData.referenceDataCache.fetchedAtMs) < FIVE_MIN;

return [{ json: { cacheValid, cached: cacheValid ? staticData.referenceDataCache.payload : null } }];

const DEFAULTS = {
  AI_ENABLED: true,
  MAX_HOURS_PER_DAY: 16,
  MAX_HOURS_PER_ENTRY: 12,
  HOURS_STEP: 0.25,
  BACKDATE_DAYS: 7,
  WORKING_DAYS: [1, 2, 3, 4, 5],
  DEFAULT_TIMEZONE: 'Asia/Kolkata',
  SESSION_TIMEOUT_MIN: 30,
  PIN_LENGTH: 6,
  PIN_MAX_ATTEMPTS: 3,
  PIN_LOCKOUT_MIN: 15,
  REVERIFY_WINDOW_MIN: 15,
  MAX_MESSAGE_CHARS: 1000,
  MAX_ENTRIES_PER_SESSION: 10,
  TASK_MIN_CHARS: 10,
  TASK_MAX_CHARS: 500,
  COMMENT_MAX_CHARS: 500,
  LOW_CONFIDENCE_THRESHOLD: 0.75,
  DUPLICATE_POLICY: 'WARN',
  HOUR_ALIASES: { 'half day': 4, 'full day': 8 },
  SENSITIVE_TERMS: []
};

const BOOLEAN_KEYS = new Set(['AI_ENABLED']);
const NUMBER_KEYS = new Set([
  'MAX_HOURS_PER_DAY', 'MAX_HOURS_PER_ENTRY', 'HOURS_STEP', 'BACKDATE_DAYS',
  'SESSION_TIMEOUT_MIN', 'PIN_LENGTH', 'PIN_MAX_ATTEMPTS', 'PIN_LOCKOUT_MIN',
  'REVERIFY_WINDOW_MIN', 'MAX_MESSAGE_CHARS', 'MAX_ENTRIES_PER_SESSION',
  'TASK_MIN_CHARS', 'TASK_MAX_CHARS', 'COMMENT_MAX_CHARS', 'LOW_CONFIDENCE_THRESHOLD'
]);
const JSON_KEYS = new Set(['HOUR_ALIASES']);
const LIST_KEYS = new Set(['WORKING_DAYS', 'SENSITIVE_TERMS']);

const rows = $input.all().map(i => i.json);
const raw = {};
for (const row of rows) {
  const key = (row.Key || '').toString().trim();
  if (!key) continue;
  raw[key] = row.Value;
}

const settings = {};
for (const key of Object.keys(DEFAULTS)) {
  const cell = raw[key];
  const hasCell = cell !== undefined && cell !== null && cell.toString().trim() !== '';

  if (!hasCell) {
    settings[key] = DEFAULTS[key];
    continue;
  }

  const str = cell.toString().trim();
  try {
    if (BOOLEAN_KEYS.has(key)) {
      settings[key] = /^true$/i.test(str);
    } else if (NUMBER_KEYS.has(key)) {
      const n = Number(str);
      settings[key] = isFinite(n) ? n : DEFAULTS[key];
    } else if (JSON_KEYS.has(key)) {
      settings[key] = JSON.parse(str);
    } else if (LIST_KEYS.has(key)) {
      settings[key] = str.split(',').map(s => {
        const t = s.trim();
        return key === 'WORKING_DAYS' ? Number(t) : t;
      }).filter(v => v !== '' && !(typeof v === 'number' && isNaN(v)));
    } else {
      settings[key] = str;
    }
  } catch (e) {
    settings[key] = DEFAULTS[key];
  }
}

return [{ json: { settings } }];

// Group ACTIVE Catalog rows into [{project, activities:[{name, sort}]}], sorted by Sort
const rows = $input.all().map(i => i.json);
const byProject = new Map();

for (const row of rows) {
  const status = (row.Status || '').toString().trim().toUpperCase();
  if (status !== 'ACTIVE') continue;
  const project = (row['Project Name'] || '').toString().trim();
  const activity = (row['Activity Type'] || '').toString().trim();
  const sortVal = Number(row.Sort || 999);
  if (!project || !activity) continue;
  if (!byProject.has(project)) byProject.set(project, []);
  byProject.get(project).push({ name: activity, sort: isNaN(sortVal) ? 999 : sortVal });
}

const catalog = Array.from(byProject.entries())
  .map(([project, items]) => {
    items.sort((a, b) => a.sort - b.sort || a.name.localeCompare(b.name));
    return {
      project,
      activities: items.map(i => i.name)
    };
  })
  .sort((a, b) => a.project.localeCompare(b.project));

const settings = $('Parse Settings').first().json.settings;
const fetchedAt = new Date().toISOString();
const payload = { settings, catalog, fetched_at: fetchedAt };

const staticData = $getWorkflowStaticData('global');
staticData.referenceDataCache = { fetchedAtMs: Date.now(), payload };

return [{ json: payload }];
